        marks: [{ name: 'ロンドン塔', lon: -0.0759, lat: 51.5081 }, { name: 'スミスフィールド（タイラーが殺された場所）', lon: -0.1005, lat: 51.5185 }, { name: 'ウェストミンスター', lon: -0.1276, lat: 51.4994 }],
